#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int totalLength;
    cin >> totalLength;
    string sequence;
    cin >> sequence;
    bool insideParentheses = false;
    string currentSegment;
    int maxSegmentLength = 0;
    int insideWordsTotal = 0;
    for (int i = 0; i < totalLength; i++) {
        char ch = sequence[i];
        if (ch == '(') {
            if (!insideParentheses) {
                vector<string> outsideParts;
                stringstream ss(currentSegment);
                string part;
                while (getline(ss, part, '_')) {
                    outsideParts.push_back(part);
                }
                for (const auto& p : outsideParts) {
                    maxSegmentLength = max(maxSegmentLength, (int)p.length());
                }
            }
            insideParentheses = true;
            currentSegment.clear();
        } else if (ch == ')') {
            insideParentheses = false;
            vector<string> insideParts;
            stringstream ss(currentSegment);
            string part;
            while (getline(ss, part, '_')) {
                if (!part.empty()) {
                    insideWordsTotal++;
                }
            }
            currentSegment.clear();
        } else {
            currentSegment += ch;
        }
    }
    vector<string> outsideRemaining;
    stringstream ss(currentSegment);
    string part;
    while (getline(ss, part, '_')) {
        outsideRemaining.push_back(part);
    }
    for (const auto& p : outsideRemaining) {
        maxSegmentLength = max(maxSegmentLength, (int)p.length());
    }
    cout << maxSegmentLength << " " << insideWordsTotal << "\n";
    return 0;
}
